UPDATE applications
SET processing_tier = 'express',
    estimated_days = estimated_days * 0.5
WHERE credit_score >= 750 AND requested_amount <= 50000;

UPDATE applications
SET processing_tier = 'priority',
    estimated_days = estimated_days * 0.75
WHERE credit_score >= 700 AND requested_amount > 50000;

UPDATE applications
SET processing_tier = 'extended',
    estimated_days = estimated_days * 1.5
WHERE credit_score < 600;

SELECT * FROM applications ORDER BY application_id;
